import java.util.Random;

/**
 * A class which is used to access the weather and handle changing
 * weather.
 *
 * @version 26/02/2022
 */
public class Weather {
    // Stores all of the possible weather types.
    public enum WeatherType { Sunny, Rainy, Foggy, Clear, Cloudy }

    private static WeatherType currentWeather = pickRandomWeather();

    private static int weatherLastsForSteps;
    private static final int MINIMUM_STEPS_WEATHER_LASTS_FOR = 27;

    // Stores a randomiser used for generating random weather.
    private static final Random rand = Randomizer.getRandom();

    /**
     * @return The current weather type.
     */
    public static WeatherType getWeather() 
    {
        if (currentWeather == null) 
        {
            currentWeather = pickRandomWeather();
        }

        return currentWeather;
    }

    /**
     * Updates the weather and picks a random weather after a
     * random amount of steps.
     */
    public static void updateWeather() 
    {
        if (weatherLastsForSteps == 0) 
        {
            currentWeather = pickRandomWeather();
        }
        else 
        {
            weatherLastsForSteps--;
        }

        // Sunny can only occur during daytime; clear can only occur at night.
        if (Time.isNight() && currentWeather == WeatherType.Sunny)
        {
            currentWeather = WeatherType.Clear;
        }

        if (!Time.isNight() && currentWeather == WeatherType.Clear)
        {
            currentWeather = WeatherType.Sunny;
        }
    }

    /**
     * @return A randomly chosen weather type, with a new duration set.
     */
    private static WeatherType pickRandomWeather() 
    {
        int randomInt = rand.nextInt(WeatherType.values().length);

        weatherLastsForSteps = rand.nextInt(20) + MINIMUM_STEPS_WEATHER_LASTS_FOR;

        return WeatherType.values()[randomInt];
    }
}

import java.util.List;

/**
 * Plants grow over time, can be partially eaten, spread to adjacent empty cells
 * (at a rate that varies by weather), and die if eaten below zero health.
 *
 * @version 26/02/2022
 */
public class Plant extends LivingOrganism
{
    // its current health percentage
    private double healthPercentage;
    // The likelihood a plants being able to spread into areas with no plants
    private double spreadProbability;
    // The rate at which plants grow back and increase their health percentage
    private static final double GROWTH_RATE = 0.05;
    // The amount of health percentage which is taken away every time an animal eats a plant
    private static final double PERCENTAGE_EATEN = 0.52;
    // The food value of itself - how much the hunter's food level increases when eating it.
    private static final int FOOD_VALUE = 3;

    /**
     * Create a new PLANT at location in field.
     * 
     * @param randomHealthPercentage If true, the plant will have a random age.
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    public Plant(boolean randomHealthPercentage, Field field, Location location) 
    {
        super(field, location);

        foodValue = FOOD_VALUE;

        healthPercentage = 1;
        if (randomHealthPercentage) 
        {
            healthPercentage = rand.nextDouble();

            if (healthPercentage < 0.1)
            {
                healthPercentage = 0.1;
            }
        }
    }

    /**
     * Grow in health, then attempt to spread to adjacent empty cells
     * during daytime. Spread probability depends on current weather.
     *
     * @param newPlants A list to receive newly spawned plants.
     */
    @Override
    public void act(List<LivingOrganism> newPlants)
    {
        incrementAge();
        if(Time.isNight() || !isAlive())
        {
            return;
        }

        switch (Weather.getWeather())
        {
            case Sunny:
                spreadProbability = 0.2;
                break;
            case Rainy:
                spreadProbability = 0.14;
                break;
            case Foggy:
                spreadProbability = 0.05;
                break;
            case Cloudy:
                spreadProbability = 0.1;
                break;
            case Clear:
                spreadProbability = 0.08;
                break;
        }

        if (rand.nextDouble() < spreadProbability)
        {
            populate(newPlants);
        }
    }

    /**
     * When called, the plant gets eaten and loses a
     * pre-defined amount of health.
     */
    protected int beEaten() 
    {
        healthPercentage -= PERCENTAGE_EATEN;
        if (healthPercentage <= 0)
        {
            setDead();
        }

        return foodValue;
    }

    /**
     * Makes the plant grow to full health.
     */
    @Override
    protected void incrementAge() 
    {
        healthPercentage += GROWTH_RATE;
        if (healthPercentage > 1.0) 
        {
            healthPercentage = 1.0;
        }
    }

    /**
     * Indicate that the plant is no longer alive.
     * It is removed from the field.
     */
    @Override
    protected void setDead()
    {
        alive = false;
        if(location != null) 
        {
            field.clear(location, Plant.class);
            location = null;
        }
    }

    /**
     * Place the plant at the new location in the given field.
     *
     * @param newLocation The plant's new location.
     */
    @Override
    protected void setLocation(Location newLocation)
    {
        if(location != null) 
        {
            field.clear(location, Plant.class);
        }

        location = newLocation;
        field.place(this, newLocation);
    }

    /**
     * Check whether or not this Plant is to give birth at this step.
     * New births will be made into free adjacent locations.
     *
     * @param newPlants A list to return newly born Plants.
     */
    @Override
    protected void populate(List<LivingOrganism> newPlants)
    {
        // Get a list of adjacent free locations.
        Field field = getField();
        List<Location> free = field.getFreeAdjacentLocations(getLocation(), Plant.class);

        // New plants are spread into adjacent locations.
        while (!free.isEmpty())
        {
            newPlants.add(createOffspring(free));
        }
    }

    private Plant createOffspring(List<Location> free)
    {
        return new Plant(false, field, free.remove(0));
    }
}

